glsl3.vert:
precision highp float;
uniform CCGlobal {
  mat4 cc_matView;
  mat4 cc_matViewInv;
  mat4 cc_matProj;
  mat4 cc_matProjInv;
  mat4 cc_matViewProj;
  mat4 cc_matViewProjInv;
  vec4 cc_cameraPos;
  vec4 cc_time;
  mediump vec4 cc_screenSize;
  mediump vec4 cc_screenScale;
};
uniform CCLocal {
  mat4 cc_matWorld;
  mat4 cc_matWorldIT;
};
in vec3 a_position;
in vec4 a_color;
out vec4 v_color;
in vec2 a_uv0;
out vec2 v_uv0;
out vec2 a_uv1;
uniform LineVert {
  vec4 tilingOffset;
};
void main () {
  vec4 pos = vec4(a_position, 1);
  #if CC_USE_MODEL
  pos = cc_matViewProj * cc_matWorld * pos;
  #else
  pos = cc_matViewProj * pos;
  #endif
  v_uv0 = a_uv0 * tilingOffset.xy + tilingOffset.zw;
  v_color = a_color;
  a_uv1 = a_uv0;
  gl_Position = pos;
}

glsl3.frag:
precision highp float;
#if USE_ALPHA_TEST
  uniform ALPHA_TEST {
    float alphaThreshold;
  };
#endif
void ALPHA_TEST (in vec4 color) {
  #if USE_ALPHA_TEST
      if (color.a < alphaThreshold) discard;
  #endif
}
void ALPHA_TEST (in float alpha) {
  #if USE_ALPHA_TEST
      if (alpha < alphaThreshold) discard;
  #endif
}
in vec4 v_color;
in vec2 a_uv1;
in vec2 v_uv0;
uniform sampler2D texture;
void main () {
  vec4 o = vec4(1, 1, 1, 1);
  vec4 texture_tmp = texture(texture, v_uv0);
  #if CC_USE_ALPHA_ATLAS_texture
      texture_tmp.a *= texture(texture, v_uv0 + vec2(0, 0.5)).r;
  #endif
  #if INPUT_IS_GAMMA
    o.rgb *= (texture_tmp.rgb * texture_tmp.rgb);
    o.a *= texture_tmp.a;
  #else
    o *= texture_tmp;
  #endif
  o *= v_color;
  ALPHA_TEST(o);
  float edge = 0.1;
  float dis = 0.0;
  vec2 texCoord = v_uv0;
  if ( texCoord.x < edge ){
      if ( texCoord.y < edge ){
          dis = distance( texCoord, vec2(edge, edge) );
      }
      if ( texCoord.y > (1.0 - edge) ){
          dis = distance( texCoord, vec2(edge, (1.0 - edge)) );
      }
  }
  else if ( texCoord.x > (1.0 - edge) ){
      if ( texCoord.y < edge ){
          dis = distance( texCoord, vec2((1.0 - edge), edge ) );
      }
      if ( texCoord.y > (1.0 - edge) ){
          dis = distance( texCoord, vec2((1.0 - edge), (1.0 - edge) ) );
      }
  }
  if(dis > 0.001)
  {
      if(dis <= edge){
          gl_FragColor = o;
      }else{
          o= vec4(0.5,0.,0.,0.);
          ALPHA_TEST(o);
          gl_FragColor = o;
      }
  }else{
      gl_FragColor = o;
  }
}

